//! Small owned table and biological record types; no GUI state is stored here.

use serde::{Deserialize, Serialize};

/// Maximum number of mouse records accepted or generated by one conversion.
pub const MAX_MICE: usize = 100_000;
/// Maximum number of columns, including metadata, in any table.
pub const MAX_COLUMNS: usize = 4_096;
/// Maximum number of cells in an input or output table, including headers.
pub const MAX_CELLS: usize = 2_000_000;
/// Maximum selected genotype hierarchy depth.
pub const MAX_GROUPS: usize = 8;

/// A parsed headered TSV, with physical line positions retained for diagnostics.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InputTable {
    /// Source column names; duplicates are supported through occurrence mappings.
    pub headers: Vec<String>,
    /// Rectangular data rows, without the header.
    pub rows: Vec<Vec<String>>,
    /// Physical starting line corresponding to each data row.
    pub source_rows: Vec<usize>,
}

/// An output table with independently rendered hierarchical header rows.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OutputTable {
    /// Stable column identities, separate from user-editable display labels.
    pub keys: Vec<String>,
    /// One header row per selected hierarchy level (one for cage expansion).
    pub headers: Vec<Vec<String>>,
    /// Read-only logical cell values.
    pub rows: Vec<Vec<String>>,
}

/// Normalized cage inventory row.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Cage {
    /// Cage identity after trimming structural whitespace.
    pub id: String,
    /// Positive mouse count.
    pub quantity: usize,
    /// Sex text, independent of its display layout.
    pub sex: String,
}

/// Semantic genotype, independent of configured source tokens and display names.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Genotype {
    /// Homozygous mutation; default source token `-/-`.
    Hom,
    /// Heterozygous; default source token `+/-`.
    Het,
    /// Wild type; default source token `+/+`.
    Wt,
    /// Missing or explicitly unknown call.
    Unknown,
}

/// Normalized per-mouse record. Presentation-only cage/sex cells never live here.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Mouse {
    /// Cage identity.
    pub cage_id: String,
    /// Cage sex.
    pub sex: String,
    /// Optional within-cage index, starting at 1.
    pub within_cage: Option<usize>,
    /// Ear label.
    pub ear: String,
    /// Positive global mouse number.
    pub mouse_number: u64,
    /// Optional plate text from the source or generated assignment.
    pub plate: Option<String>,
    /// Optional well text from the source or generated assignment.
    pub well: Option<String>,
    /// Calls in selected gene hierarchy order.
    pub genotypes: Vec<Genotype>,
    /// Unmodified free-text remark.
    pub remark: String,
    /// Source line used in diagnostics.
    pub source_row: usize,
}
